use super::{reader,shared};
use shared::units::{LengthUnitControl,LengthUnitLimits,LengthUnitResult,LengthUnitWork};
use crate::standards::v4::subsets::any::schema::snapshot::from_part21_document;
fn document(data:&str)->super::IfcSnapshot{let source=format!("ISO-10303-21;HEADER;FILE_DESCRIPTION((''),'2;1');FILE_NAME('','',(''),(''),'','','');FILE_SCHEMA(('IFC4'));ENDSEC;DATA;{}ENDSEC;END-ISO-10303-21;",data);from_part21_document("stdio.ifc",&semio_s_artifact_stdio_contract::part21::parse_part21(&source).unwrap())}
#[semio_framework_async_macros::async_test]
async fn neutral_length_units_resume_and_close(){let cases:semio_framework_pack_json::Value=semio_framework_pack_json::parse(include_str!("../../../../../../../📐️geometry/📏️units/🧪️tests/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for case in cases["cases"].as_array().unwrap(){let source=document(case["data"].as_str().unwrap());let graph=reader::Ifc4GeometryGraph(&source);let mut work=LengthUnitWork::new(1,7,LengthUnitLimits::default());let mut result=LengthUnitResult::Pending;for _ in 0..10000{let before=work.work;result=work.advance(&graph,7,1,&mut |_|LengthUnitControl::Continue);assert!(work.work-before<=1);if result!=LengthUnitResult::Pending{break}}match result{LengthUnitResult::Resolved{metres_per_unit,..}=>{assert_eq!(case["expected"]["status"].as_str(),Some("resolved"));let expected=case["expected"]["metresPerUnit"].as_f64().unwrap();assert!((metres_per_unit-expected).abs()<=expected.abs()*1e-14,"{:?}",case["name"]);},LengthUnitResult::Invalid{reason,..}=>{assert_eq!(case["expected"]["status"].as_str(),Some("invalid"));assert_eq!(Some(reason),case["expected"]["reason"].as_str(),"{:?}",case["name"]);},other=>panic!("unexpected {:?} for {:?}",other,case["name"])}assert!(!work.close(0,&mut |_|LengthUnitControl::Continue));let mut closed=false;for _ in 0..10000{let before=work.work;closed=work.close(1,&mut |_|LengthUnitControl::Continue);assert!(work.work-before<=1);if closed{break}}assert!(closed);}}
#[semio_framework_async_macros::async_test]
async fn original_identity_revision_and_zero_work_cancellation(){let a=document("#1=IFCPROJECT('0AAAAAAAAAAAAAAAAAAAAA',$,$,$,$,$,$,$,#2);#2=IFCUNITASSIGNMENT((#3));#3=IFCSIUNIT(*,.LENGTHUNIT.,$,.METRE.);");let b=a.clone();let mut work=LengthUnitWork::new(1,7,LengthUnitLimits::default());assert_eq!(work.advance(&reader::Ifc4GeometryGraph(&a),7,1,&mut |_|LengthUnitControl::Continue),LengthUnitResult::Pending);assert!(matches!(work.advance(&reader::Ifc4GeometryGraph(&b),7,100,&mut |_|LengthUnitControl::Continue),LengthUnitResult::Invalid{reason:"source-version-changed",..}));assert!(work.close(100,&mut |_|LengthUnitControl::Continue));let mut cancelled=LengthUnitWork::new(1,7,LengthUnitLimits::default());assert_eq!(cancelled.advance(&reader::Ifc4GeometryGraph(&a),7,0,&mut |_|LengthUnitControl::Cancel),LengthUnitResult::Cancelled);assert_eq!(cancelled.work,0);assert!(cancelled.close(0,&mut |_|LengthUnitControl::Continue));}
#[semio_framework_async_macros::async_test]
async fn unchanged_official_units(){for(source,project,expected)in[(include_str!("../../../🧪️tests/🧫️fixtures/🏛️official/column-straight-rectangle-tessellation.ifc"),37,0.0254),(include_str!("../../../🧪️tests/🧫️fixtures/🏛️official/polygonal-face-tessellation.ifc"),3061,0.001),(include_str!("../../../🧪️tests/🧫️fixtures/🏛️official/tessellation-with-individual-colors.ifc"),100,0.001)]{let snapshot=from_part21_document("stdio.ifc",&semio_s_artifact_stdio_contract::part21::parse_part21(source).unwrap());let graph=reader::Ifc4GeometryGraph(&snapshot);let mut work=LengthUnitWork::new(project,7,LengthUnitLimits::default());let mut result=LengthUnitResult::Pending;for _ in 0..10000{result=work.advance(&graph,7,3,&mut |_|LengthUnitControl::Continue);if result!=LengthUnitResult::Pending{break}}assert!(matches!(result,LengthUnitResult::Resolved{metres_per_unit,..}if(metres_per_unit-expected).abs()<1e-14));assert!(work.close(10000,&mut |_|LengthUnitControl::Continue));}}

#[semio_framework_async_macros::async_test]
async fn latched_cancellation_still_allows_controlled_close(){let source=document("#1=IFCPROJECT('0AAAAAAAAAAAAAAAAAAAAA',$,$,$,$,$,$,$,#2);#2=IFCUNITASSIGNMENT((#3));#3=IFCSIUNIT(*,.LENGTHUNIT.,$,.METRE.);");let graph=reader::Ifc4GeometryGraph(&source);let mut work=LengthUnitWork::new(1,7,LengthUnitLimits::default());work.advance(&graph,7,2,&mut |_|LengthUnitControl::Continue);assert_eq!(work.advance(&graph,7,0,&mut |_|LengthUnitControl::Cancel),LengthUnitResult::Cancelled);let mut closed=false;for _ in 0..1000{let before=work.work;closed=work.close(1,&mut |_|LengthUnitControl::Cancel);assert!(work.work-before<=1);if closed{break}}assert!(closed);}
